  private void rememberTypeShape(Class<?> type) {
    if (type == null) {
      typeShapeLatest = "";
      typeShapeKind = 0;
      typeShapePrimitive = false;
      typeShapeWrapper = null;
      return;
    }
    typeShapeLatest = type.getName();
    typeShapePrimitive = type.isPrimitive();
    typeShapeKind = typeShapePrimitive ? 1 : (classifyWrapper(type) ? 2 : 0);
    typeShapeWrapper = typeShapePrimitive ? wrapJavaType(type) : type;
    typeShapeJournal.put("remember:" + type.getName(), String.valueOf(typeShapeKind));
  }

