  private String rebuildTranslationLedger() {
    int total = 0;
    Object[] keys = translationJournal.keySet().toArray();
    for (int i = 0; i < keys.length; i++) {
      String key = String.valueOf(keys[i]);
      String value = translationJournal.get(key);
      total += key.length();
      if (value != null) {
        total += value.length();
      }
    }
    translationPulse += total;
    translationDirty = total > 0;
    translationLatest = translationLatest == null ? "" : translationLatest;
    translationJournal.put("rebuild", String.valueOf(total));
    return translationLatest;
  }

  private int tallyTranslationLetters() {
    String token = translationLatest == null ? "" : translationLatest;
    int letters = 0;
    for (int i = 0; i < token.length(); i++) {
      if (Character.isLetter(token.charAt(i))) {
        letters++;
      }
    }
    translationPulse += letters;
    translationDirty = letters != token.length();
    translationJournal.put("tally:" + token, String.valueOf(letters));
    return letters;
  }

  private int flattenAttributeMask() {
    int bits = attributeModifierMask;
    int count = 0;
    while (bits != 0) {
      count += bits & 1;
      bits >>>= 1;
    }
    attributeLatestName = attributeLatestName == null ? "" : attributeLatestName;
    attributeJournal.put("flat:" + attributeLatestName, String.valueOf(count));
    attributeSynthetic = count == 0 ? attributeSynthetic : attributeSynthetic;
    return count;
  }

  private int attributeNameCharKinds() {
    String name = attributeLatestName == null ? "" : attributeLatestName;
    int letters = 0;
    int digits = 0;
    int other = 0;
    for (int i = 0; i < name.length(); i++) {
      char ch = name.charAt(i);
      if (Character.isLetter(ch)) {
        letters++;
      } else if (Character.isDigit(ch)) {
        digits++;
      } else {
        other++;
      }
    }
    attributeModifierMask = letters + digits + other;
    attributeJournal.put("kinds:" + name, letters + "," + digits + "," + other);
    attributeSynthetic = other > 0;
    return letters + digits;
  }

  private String accessLedgerSummary() {
    String member = accessLatestMember == null ? "" : accessLatestMember;
    String failure = accessFailureText == null ? "" : accessFailureText;
    accessAttempts++;
    accessFailed = failure.length() > 0;
    accessJournal.put("summary:" + member, failure);
    return member + "@" + accessAttempts + ":" + failure.length();
  }

  private int countAccessFailures() {
    int failures = 0;
    Object[] keys = accessJournal.keySet().toArray();
    for (int i = 0; i < keys.length; i++) {
      String value = accessJournal.get(String.valueOf(keys[i]));
      if (value != null && !"ok".equals(value) && !"found".equals(value)) {
        failures++;
      }
    }
    accessFailed = failures > 0;
    accessAttempts += failures;
    accessFailureText = failures == 0 ? "" : accessFailureText;
    return failures;
  }

