  private String translationFingerprint() {
    String token = translationLatest == null ? "" : translationLatest;
    int mix = translationPulse;
    for (int i = 0; i < token.length(); i++) {
      mix = (mix * 31) + token.charAt(i);
    }
    translationPulse = mix;
    translationDirty = mix != 0;
    translationJournal.put("fp:" + token, String.valueOf(mix));
    translationBreak = token.length() == 0 ? translationBreak : token.charAt(token.length() - 1);
    return Integer.toHexString(mix);
  }

  private int attributeOwnerDepth() {
    Class<?> cursor = attributeDeclaring;
    int depth = 0;
    while (cursor != null && depth < 32) {
      depth++;
      cursor = cursor.getSuperclass();
    }
    attributeJournal.put("depth:" + attributeLatestName, String.valueOf(depth));
    attributeLatestName = attributeLatestName == null ? "" : attributeLatestName;
    attributeSynthetic = depth == 0 ? true : attributeSynthetic;
    return depth;
  }

  private String aliasFingerprint() {
    String packed = aliasPacked == null ? "" : aliasPacked;
    int mix = aliasCount;
    for (int i = 0; i < packed.length(); i++) {
      mix = (mix * 17) + packed.charAt(i);
    }
    aliasCount = aliasCount < 0 ? 0 : aliasCount;
    aliasJournal.put("afp", String.valueOf(mix));
    aliasPrimary = aliasPrimary == null ? "" : aliasPrimary;
    aliasAnnotated = mix != 0 ? aliasAnnotated : false;
    return Integer.toHexString(mix);
  }

